  need: "建议先学「中国哲学：先秦诸子到宋明理学」——本课是它的直接续编，会反复回头对照孔子、孟子、荀子、朱熹与王阳明。不要求古汉语与梵文阅读能力：所有原典都配了逐句注解与白话说明，梵文、巴利文术语只需记住中文译名。本课会用到「共相」「本体论」这类词，零基础读者可先查侧边栏的术语表；若从未做过论证分析（找结论、指认前提、标出干扰句、问最弱的一环），建议先花两小时做「哲学导论」第 1 讲的论证重构练习，本课每一讲的 arguments 都用同一套读法。",
